import{_ as e}from"./chunks/image12.BRgDBKom.js";import{_ as a,o,c as i,am as r}from"./chunks/framework.CenUaW7a.js";const n="/projects/AiMechaM1/en/advanced-kit/assets/image1.DlDcM6WT.webp",s="/projects/AiMechaM1/en/advanced-kit/assets/image2.C7ye25_0.png",l="/projects/AiMechaM1/en/advanced-kit/assets/image3.BAmMrE6G.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image4.qMGUzWPz.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image5.DjeyXVnb.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image6.m0iQEaqF.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image7.CyJjIwwr.png",x=JSON.parse('{"title":"3.21 Lesson 21: Target Tracking and Positioning","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.21 Lesson 21 Target Tracking and Positioning.md","filePath":"docs/3. Course materials/3.21 Lesson 21 Target Tracking and Positioning.md"}'),h={name:"docs/3. Course materials/3.21 Lesson 21 Target Tracking and Positioning.md"};function m(u,t,f,b,w,y){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_3-21-lesson-21-target-tracking-and-positioning" tabindex="-1">3.21 Lesson 21: Target Tracking and Positioning <a class="header-anchor" href="#_3-21-lesson-21-target-tracking-and-positioning" aria-label="Permalink to &quot;3.21 Lesson 21: Target Tracking and Positioning&quot;">​</a></h1><h2 id="_3-21-1-lesson-introduction" tabindex="-1">3.21.1 Lesson Introduction <a class="header-anchor" href="#_3-21-1-lesson-introduction" aria-label="Permalink to &quot;3.21.1 Lesson Introduction&quot;">​</a></h2><p>This lesson transitions from categorical recognition to dynamic target tracking, initiating visual servo control. Taking inspiration from star athlete tracking and drone aerial follow shots, this lesson explores the principles of target tracking. Image coordinate systems are introduced for the first time alongside K230 bounding-box target locking and tracking technology. By completing two tasks, horizontal car tracking and vertical robotic arm pitch tracking, a two-axis tracking system is constructed. For the first time, &quot;visual closed-loop&quot; control is implemented by learning coordinate-to-deviation conversion and servo adjustment to understand feedback control principles, expanding the application boundaries of the K230 module and establishing control theory foundations for automatic following.</p><h2 id="_3-21-2-learning-objectives" tabindex="-1">3.21.2 Learning Objectives <a class="header-anchor" href="#_3-21-2-learning-objectives" aria-label="Permalink to &quot;3.21.2 Learning Objectives&quot;">​</a></h2><ol><li><p>Understand the definition of image coordinate systems and master coordinate representation methods for target positions alongside the technical principles of target tracking.</p></li><li><p>Manually frame target objects on the K230 module and initiate tracking. Proficiently read parameters such as the target center x-coordinate, center y-coordinate, width, and height. Write programs to control left and right car tracking based on x-coordinate deviations.</p></li><li><p>Establish a coordinate-based spatial mindset to describe positions and deviations using numerical values. Cultivate a closed-loop control mindset by understanding the feedback loop of &quot;detecting deviation → adjusting actions → reducing deviation&quot;.</p></li><li><p>Connect target tracking technology to real-world application scenarios such as automated security camera tracking, drone follow shots, autonomous vehicle target tracking, and camera face-recognition tracking, understanding the broad value of target tracking technology across various fields.</p></li></ol><h2 id="_3-21-3-preparation" tabindex="-1">3.21.3 Preparation <a class="header-anchor" href="#_3-21-3-preparation" aria-label="Permalink to &quot;3.21.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-Wheel Car Advanced Kit</p></li><li><p>Type-C data cable</p></li><li><p>Computer × 1</p></li><li><p>Remote controller</p></li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Image Coordinate System Description</strong>:</p><ul><li><p><strong>Origin Position</strong>: The top-left corner of the frame serves as the coordinate origin (0, 0).</p></li><li><p><strong>X-Axis Direction</strong>: Extends horizontally to the right, ranging from 0 to 319 pixels.</p></li><li><p><strong>Y-Axis Direction</strong>: Extends vertically downward, ranging from 0 to 239 pixels.</p></li><li><p><strong>Frame Center</strong>: Located at approximately (160, 120).</p></li><li><p><strong>Target Size</strong>: Represented by width w and height h in pixels.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller.</p></li><li><p>Connect the three bus servos in series to bus port S1 or S2 with IDs 1, 2, and 3.</p></li><li><p>Mount the camera at a height level with the center of the target for optimal tracking performance.</p></li></ul><p><strong>Target Tracking Operating Workflow</strong>:</p><ul><li><p>Select &quot;target tracking&quot; mode on the K230 module.</p></li><li><p>Use a finger to draw a bounding box around the target object on the screen.</p></li><li><p>The module automatically extracts target features and initiates locked tracking.</p></li><li><p>Read target coordinates in the program and drive actuators accordingly.</p></li></ul><p><strong>Control Parameter Description</strong>:</p><ul><li><p>X-Axis Center Thresholds: Left threshold 140, right threshold 180, creating a 40-pixel central dead zone.</p></li><li><p>Y-Axis Center Thresholds: Central reference line 120, offset threshold 20 pixels.</p></li><li><p>Car Tracking Power: 20%, providing low speed for stable tracking.</p></li><li><p>Robotic Arm Step Size: Adjusts by 10 servo units per step.</p></li><li><p>Action Duration: Stepped adjustments at 0.5 s intervals.</p></li></ul><h2 id="_3-21-4-hands-on-project" tabindex="-1">3.21.4 Hands-On Project <a class="header-anchor" href="#_3-21-4-hands-on-project" aria-label="Permalink to &quot;3.21.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This lesson constructs a dual-axis visual servo tracking system capable of horizontal movement and vertical pitch tracking, centered around deviation-driven closed-loop control. The K230 continuously captures and outputs target center coordinate parameters. The decision-making layer sets dead-zone segmented thresholds: targets shifted left or right drive the car left or right accordingly, while vertical shifts control robotic arm pitch. The execution layer adjusts Mecanum translations and servo pitches in 0.5 s steps to form a continuous feedback loop of detection, evaluation, adjustment, and re-detection. Operating at approximately 30 frames per second, the system continuously corrects deviations to keep the target centered for automated tracking.</p><img loading="lazy" height="540" width="960" src="'+n+'" class="common_img" style="width:400px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="873" width="1150" src="'+s+'" class="common_img" style="width:300px;aspect-ratio:1150 / 873;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Target detection</td><td style="text-align:center;"><img loading="lazy" height="86" width="403" src="'+l+'" class="common_img" style="width:100px;aspect-ratio:403 / 86;"></td><td style="text-align:left;">Determines whether a target is successfully tracked and returns a boolean value.</td></tr><tr><td style="text-align:center;">Coordinate parameters</td><td style="text-align:center;"><img loading="lazy" height="222" width="710" src="'+c+'" class="common_img" style="width:100px;aspect-ratio:710 / 222;"></td><td style="text-align:left;">Reads the horizontal center x coordinate ranging from 0 to 319 and the vertical center y coordinate ranging from 0 to 239 of the target.</td></tr><tr><td style="text-align:center;">Motion control</td><td style="text-align:center;"><img loading="lazy" height="60" width="490" src="'+d+'" class="common_img" style="width:100px;aspect-ratio:490 / 60;"></td><td style="text-align:left;">Controls left and right car movement using percentage power to achieve horizontal tracking.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Mecanum-Wheel Car Tracking Target Object Horizontally</strong></p><ul><li><p>Variable preparation: Create a <code>vertical offset</code> variable to store deviation calculations, and a robotic arm ID 3 variable to store servo position values.</p></li><li><p>Initialization settings: At startup, wait 1 s for the module to start up, initialize port A, set the running mode to Target Tracking, start detection, set the robotic arm ID 3 variable to 500 for the middle position, set vertical offset to 0, and reset servo ID 3 to position 500.</p></li><li><p>Main loop structure: Execute <code>Update and save result data</code> as the first step inside the repeat forever loop.</p></li><li><p>Target presence evaluation: In the outer layer, check <code>Is Target Detected?</code>, executing tracking logic only when a target is detected and stopping the car otherwise.</p></li><li><p>Right shift branch: If <code>Center X Coordinate &gt; 180</code>, indicating the target is on the right side of the frame, set the car to move right at 20% power and wait 0.5 s.</p></li><li><p>Left shift branch: In the nested <code>else if</code> branch, check whether the <code>Center X Coordinate &lt; 140</code>, indicating the target is on the left side of the frame. Set the car to move left at 20% power and wait 0.5 s.</p></li><li><p>Centered branch: In the else if branch where the X coordinate lies between 140 and 180 inside the dead zone, stop the Mecanum-wheel car because the target is centered and requires no adjustment.</p></li><li><p>Target lost: The outermost else branch stops the car, standing by in place when the target is lost.</p></li></ul><img loading="lazy" height="869" width="949" src="'+g+'" class="common_img" style="width:600px;aspect-ratio:949 / 869;"><p><strong>Task 2: Robotic Arm Tracking Target Object Vertically</strong></p><ul><li>Reference explanation: The Y-axis ranges from 0 to 239 with a central reference value of 120, where larger Y values indicate positions lower down in the frame.</li><li>Lower half branch: If <code>Center Y Coordinate &gt; 120</code>, meaning the target is in the lower half of the frame, calculate offset = Y coordinate - 120. If the offset is less than 20, indicating closeness to the center, set robotic arm ID 3 to 300 for the low position. Otherwise, subtract 10 from robotic arm ID 3 to adjust downward. Finally, set servo ID 3 to the variable value with a running time of 500 ms.</li><li>Upper half branch: In the else if branch where <code>Center Y Coordinate &lt; 120</code>, meaning the target is in the upper half of the frame, calculate offset = 120 - Y coordinate. If the offset is less than 20, set robotic arm ID 3 variable to 500 for the middle-high position. Otherwise, increase the robotic arm ID 3 variable by 10 to adjust upward. Finally, set the position of servo ID 3 to the variable value.</li><li>Program outcome: As the target moves upward, the robotic arm lifts accordingly. As the target moves downward, the robotic arm lowers accordingly, continuously maintaining alignment between the robotic arm height and the target.</li><li>Stepped adjustment: Adjust by only 10 units at a time to prevent overshoot and achieve smooth tracking performance.</li></ul><img loading="lazy" height="676" width="581" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:581 / 676;"><p><strong>Debugging and Parameter Optimization</strong></p><ul><li><p>Dead zone size: The range from 140 to 180 provides a 40-pixel dead zone. Making it too narrow causes frequent jitter, while making it too wide reduces tracking sensitivity, which should be tuned according to actual performance.</p></li><li><p>Tracking speed: 20% power suits slow and stable tracking, while faster-moving targets require appropriately increasing the power percentage.</p></li><li><p>Step duration: 0.5 s intervals provide stepped adjustments. Shorter step lengths yield faster response but risk jitter, whereas longer step lengths yield smoother movement at the cost of latency.</p></li><li><p>Target selection: Objects with distinct colors and rich textures provide the best tracking performance, whereas pure black, pure white, or featureless objects are easily lost.</p></li><li><p>Lighting influence: Uniform lighting ensures stable tracking, whereas backlighting or dim lighting obscures features and causes lost targets.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Target Tracking and Localization</a>.</strong></p></div></li></ul><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+e+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-21-5-expansion-and-advancement" tabindex="-1">3.21.5 Expansion and Advancement <a class="header-anchor" href="#_3-21-5-expansion-and-advancement" aria-label="Permalink to &quot;3.21.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Dual-Axis Linkage Target Following Car</strong></p><p>Combine X-axis car tracking with Y-axis robotic arm tracking into a single program to achieve simultaneous horizontal and vertical dual-axis tracking. Further incorporate width parameter evaluations to control distance: an increasing target width indicates approaching, prompting the car to back up, while a decreasing target width indicates distancing, prompting the car to move forward, achieving three-dimensional distance following. This builds an intelligent following car capable of locking on and maintaining distance automatically, simulating the complete functions of an autonomous drone follow-shot system.</p><p><strong>Expansion Project 2: Multi-Target Switching Tracking System</strong></p><p>Design a multi-target management program: when multiple targets appear in the frame, automatically select the largest target to track, and automatically search to re-acquire the target once it is lost. Incorporate button-switching functionality, using Button A to switch to the next target. Explore multi-target management mechanisms in target tracking algorithms, understand concepts of target ID allocation and trajectory association, and experience how complex visual tracking systems operate.</p><h2 id="_3-21-6-q-a" tabindex="-1">3.21.6 Q&amp;A <a class="header-anchor" href="#_3-21-6-q-a" aria-label="Permalink to &quot;3.21.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Why is the origin of the image coordinate system set at the top-left corner with the Y-axis extending downward instead of upward?</strong></p><p><strong>Answer</strong>: Setting the origin at the top-left corner with the Y-axis extending downward is an industry standard determined by a combination of <strong>historical convention + hardware characteristics</strong>, adopted by virtually all image processing systems.</p><p><strong>Q2: Why does the tracking program in this lesson incorporate a dead zone design where the car remains stationary when the target stays within a certain central range?</strong></p><p><strong>Answer</strong>: The dead zone, also known as the insensitivity zone, is a classic design in control systems that <strong>trades a small amount of precision for system stability</strong>.</p><h2 id="_3-21-7-technical-support-and-discussion" tabindex="-1">3.21.7 Technical Support and Discussion <a class="header-anchor" href="#_3-21-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.21.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',50)])])}const _=a(h,[["render",m]]);export{x as __pageData,_ as default};
